        current = [a_interval[0], a_interval[1]]

        for b_interval in b_merged:
            if current[1] <= b_interval[0] or current[0] >= b_interval[1]:
                # No overlap
                continue

            if b_interval[0] <= current[0] and b_interval[1] >= current[1]:
                # b completely covers current
                current = None
                break
            elif b_interval[0] <= current[0]:
                # b covers the start
                current[0] = b_interval[1]
